#include <signal.h>
#include <threads.h>
#include <stdio.h>
#include <math.h>
#include <fenv.h>
void f(FILE *fp, double x){mtx_t m; cnd_t cv; fenv_t env; double y;
raise(SIGTERM);
thrd_yield();
mtx_lock(&m);
fseek(fp, -4, SEEK_END);
y = floor(x);
cnd_signal(&cv);
fegetenv(&env);
}

